import json,re,collections,cls,detail
K=detail.K
def D(*a): return dict(zip(K,a))
DET={
'palate':D('Palatum molle adalah bagian lunak langit-langit di belakang palatum durum; ujung bebasnya membentuk uvula.','Menutup nasofaring saat menelan dan berbicara agar makanan tidak masuk hidung.','N. vagus (X) untuk otot (kecuali tensor veli palatini oleh V3); sensasi dari n. palatina minor (V2) dan IX.','A. palatina asendens, a. palatina desendens, a. faringea asendens.','Palatum durum, nasofaring, orofaring, tonsil palatina, lidah.','Celah langit-langit, sleep apnea, paresis palatum pada lesi vagus (uvula deviasi).'),
'gingiva':D('Jaringan lunak mukosa yang mengelilingi leher gigi dan menutupi tulang alveolar.','Menyegel dan melindungi jaringan periodontal dan akar gigi.','N. alveolaris superior (V2); n. alveolaris inferior, n. lingualis, n. bukalis (V3).','A. alveolaris superior dan inferior, a. palatina mayor, a. labialis.','Gigi, tulang alveolar, ligamen periodontal, bibir dan pipi.','Gingivitis, periodontitis, resesi gingiva, hiperplasia gusi akibat obat.'),
'tongue':D('Organ otot di dasar mulut dengan otot intrinsik dan ekstrinsik; permukaan atasnya ditutupi papila pengecap.','Mengecap, mengunyah, menelan, dan berbicara.','Motorik: n. hipoglosus (XII); sensasi 2/3 depan: n. lingualis (V3), rasa: korda timpani (VII); 1/3 belakang: n. glosofaringeus (IX).','A. lingualis (cabang a. karotis eksterna).','Mandibula, tulang hioid, palatum, tonsil lingual, epiglotis.','Glositis, karsinoma sel skuamosa lidah, deviasi lidah pada lesi XII, makroglosia.'),
'parotid':D('Kelenjar ludah terbesar, di depan telinga dan di atas ramus mandibula; ditembus oleh n. fasialis.','Menghasilkan ludah serosa kaya amilase.','Parasimpatis: n. glosofaringeus (IX) via ganglion otikum dan n. aurikulotemporalis; sensorik n. aurikularis magnus.','A. karotis eksterna dan cabangnya (a. temporalis superfisialis).','N. fasialis (pleksus parotis), ramus mandibula, otot masseter, v. retromandibularis.','Parotitis (gondongan), adenoma pleomorfik, batu kelenjar, cedera n. fasialis saat operasi.'),
'sublingual':D('Kelenjar ludah utama terkecil, di bawah lidah pada dasar mulut.','Menghasilkan ludah mukus.','Parasimpatis: korda timpani (VII) via ganglion submandibula.','A. sublingualis dan a. submentalis.','Dasar mulut, mandibula, duktus submandibula, n. lingualis.','Ranula (kista mukus), batu kelenjar.'),
'submandibular':D('Kelenjar ludah di bawah mandibula; duktusnya (Wharton) bermuara di sisi frenulum lidah.','Menghasilkan ludah campuran serosa dan mukus (sekitar 70% ludah basal).','Parasimpatis: korda timpani (VII) via ganglion submandibula.','A. fasialis dan a. lingualis.','Otot mylohyoid, n. lingualis, n. hipoglosus, a. fasialis.','Sialolitiasis (batu kelenjar, tersering di sini), sialadenitis.'),
'salivary_duct':D('Saluran yang membawa ludah ke rongga mulut: duktus parotis (Stensen) dan duktus submandibula (Wharton).','Menyalurkan ludah dari kelenjar ke mulut.','Mengikuti kelenjar asal (parasimpatis IX untuk parotis, VII untuk submandibula).','Cabang a. karotis eksterna.','Pipi (otot bukinator) untuk duktus parotis; dasar mulut dan n. lingualis untuk duktus submandibula.','Sumbatan oleh batu, striktur, radang duktus.'),
'esophagus':D('Tabung otot sekitar 25 cm dari faring (setinggi C6), menembus diafragma di T10 menuju kardia lambung.','Menyalurkan makanan ke lambung dengan gerak peristaltik; sfingter atas dan bawah mencegah refluks.','N. vagus (X) dan trunkus simpatikus; pleksus esofagus; n. laringeus rekuren untuk bagian atas.','A. tiroidea inferior (servikal), cabang aorta toraks (toraks), a. gastrika kiri dan a. frenika inferior (abdominal).','Trakea, aorta, atrium kiri, diafragma (hiatus esofagus), lambung.','GERD, esofagitis, akalasia, varises esofagus (hipertensi portal), karsinoma, hernia hiatus.'),
'stomach':D('Organ berbentuk J dengan kardia, fundus, korpus, antrum, dan pilorus; kelengkungan mayor dan minor.','Menyimpan dan mencerna makanan secara kimia (HCl, pepsin) dan mekanik; faktor intrinsik untuk vitamin B12.','N. vagus (parasimpatis, merangsang sekresi dan gerak); pleksus seliakus (simpatis T6–T9).','A. gastrika kiri dan kanan, a. gastroepiploika kanan dan kiri, a. gastrika pendek.','Esofagus, duodenum, hati, pankreas, limpa, kolon transversum, diafragma, omentum.','Tukak lambung, gastritis (H. pylori), karsinoma lambung, stenosis pilorus.'),
'stomach_mucosa':D('Lapisan dalam lambung berlipat (rugae) dengan kelenjar penghasil asam dan pepsinogen.','Menyekresi HCl, pepsinogen, mukus, dan faktor intrinsik.','N. vagus (X) dan pleksus mienterikus.','Cabang a. gastrika dan a. gastroepiploika.','Lapisan otot lambung, lumen lambung.','Gastritis, tukak, metaplasia intestinal, karsinoma lambung.'),
'duodenum':D('Bagian pertama usus halus sekitar 25 cm berbentuk C yang melingkari kepala pankreas; terdiri dari 4 bagian.','Menetralkan asam lambung, mencampur kimus dengan empedu dan enzim pankreas; tempat utama penyerapan zat besi.','N. vagus (X); pleksus seliakus dan mesenterika superior (simpatis).','A. gastroduodenalis dan a. pankreatikoduodenalis superior (truncus coeliacus), a. pankreatikoduodenalis inferior (a. mesenterika superior).','Pilorus, pankreas, duktus koledokus (papila mayor), ginjal kanan, v. kava inferior.','Tukak duodenum, duodenitis, obstruksi, karsinoma kepala pankreas yang menekan duodenum.'),
'jejunum':D('Bagian usus halus setelah duodenum dengan lipatan sirkular (plica) yang tebal; pada atlas ini termasuk bagian usus halus berikutnya.','Penyerapan utama nutrien: karbohidrat, protein, lemak.','N. vagus; pleksus mesenterika superior (simpatis T9–T10).','A. mesenterika superior (aa. jejunales), v. mesenterika superior.','Duodenum (fleksura duodenojejunalis), mesenterium, kolon transversum.','Penyakit Crohn, penyakit seliak, obstruksi usus halus, sindrom usus pendek.'),
'appendix':D('Tabung buntu kecil (sekitar 8–10 cm) yang menempel pada sekum di bawah katup ileosekal.','Mengandung jaringan limfoid; diduga reservoir flora usus.','N. vagus dan pleksus mesenterika superior; nyeri visceral awal dirasakan di sekitar pusar (T10).','A. apendikularis (cabang a. ileokolika).','Sekum, ileum terminal, mesoapendiks; titik McBurney di permukaan kulit.','Apendisitis akut (nyeri berpindah ke kuadran kanan bawah), perforasi, apendektomi.'),
'colon_asc':D('Kolon naik di sisi kanan abdomen dari sekum ke fleksura hepatika; retroperitoneal.','Menyerap air dan elektrolit dari kimus cair.','N. vagus dan pleksus mesenterika superior (simpatis).','A. ileokolika dan a. kolika kanan (a. mesenterika superior).','Sekum, ileum terminal, ginjal kanan, hati (fleksura hepatika), dinding abdomen.','Karsinoma kolon kanan, penyakit Crohn, intususepsi.'),
'colon_trans':D('Kolon yang melintang abdomen dari fleksura hepatika ke fleksura splenika; intraperitoneal dengan mesokolon transversum.','Penyerapan air dan pembentukan feses.','N. vagus untuk 2/3 proksimal; saraf splanknik pelvis (S2–S4) untuk 1/3 distal.','A. kolika media (a. mesenterika superior), a. kolika kiri (a. mesenterika inferior).','Lambung dan omentum mayus (atas), usus halus, pankreas, limpa dan hati di kedua ujungnya.','Volvulus, karsinoma, megakolon toksik.'),
'colon_desc':D('Kolon turun di sisi kiri abdomen dari fleksura splenika ke fossa iliaka kiri; retroperitoneal.','Penyerapan air dan penyimpanan feses.','Saraf splanknik pelvis (S2–S4); pleksus mesenterika inferior (simpatis L1–L2).','A. kolika kiri dan aa. sigmoid (a. mesenterika inferior).','Ginjal kiri, limpa, m. psoas, kolon sigmoid.','Divertikulosis dan divertikulitis, kolitis ulseratif, karsinoma kolon kiri.'),
'colon_sig':D('Segmen berbentuk S setelah kolon desendens menuju rektum; intraperitoneal dengan mesokolon sigmoid.','Penyimpanan feses dan pengaturan pengosongan.','Saraf splanknik pelvis (S2–S4) dan pleksus hipogastrik inferior.','Aa. sigmoid dan a. rektalis superior (a. mesenterika inferior).','Kandung kemih, uterus atau prostat, ureter kiri, rektum.','Volvulus sigmoid, divertikulitis (tersering), karsinoma kolorektal.'),
'taenia':D('Tiga pita otot longitudinal (taenia libera, mesokolika, omentalis) pada dinding kolon yang membentuk haustra.','Memendekkan kolon dan membentuk kantung haustra untuk gerak segmentasi.','Pleksus mienterikus; n. vagus dan saraf splanknik pelvis.','Aa. kolika (a. mesenterika superior dan inferior).','Sekum, kolon, apendiks (ketiga taenia bertemu di dasar apendiks), omentum.','Petunjuk bedah untuk menemukan apendiks; divertikel muncul di celah antar taenia.'),
'liver':D('Kelenjar terbesar tubuh (sekitar 1,5 kg) di kuadran kanan atas; lobus kanan, kiri, kaudatus, dan kuadratus; dibagi menjadi 8 segmen Couinaud.','Metabolisme nutrien, sintesis protein plasma dan faktor pembekuan, detoksifikasi, produksi empedu, penyimpanan glikogen dan vitamin.','N. vagus, n. frenikus (kapsul), pleksus seliakus (simpatis T7–T10).','A. hepatika (sekitar 25%, beroksigen) dan v. porta (sekitar 75%, dari usus); keluar lewat vv. hepatika ke v. kava inferior.','Diafragma, lambung, kandung empedu, duodenum, ginjal kanan, v. kava inferior.','Hepatitis, sirosis, hipertensi portal, karsinoma hepatoseluler, perlemakan hati, laserasi hati.'),
'liver_seg':D('Segmen fungsional Couinaud (I–VIII); masing-masing punya cabang v. porta, a. hepatika, dan duktus empedu sendiri.','Memungkinkan reseksi hati per segmen tanpa mengganggu segmen lain.','Pleksus hepatikus (n. vagus dan simpatis).','Cabang segmental a. hepatika dan v. porta; drainase oleh vv. hepatika.','Segmen lain, fisura dan ligamen falsiformis, v. porta, kandung empedu.','Hepatektomi segmental, lokalisasi tumor dan abses hati.'),
'gallbladder':D('Kantung berbentuk buah pir di bawah hati dengan fundus, korpus, infundibulum, dan leher (duktus sistikus).','Menyimpan dan memekatkan empedu; berkontraksi saat dirangsang CCK setelah makan berlemak.','N. vagus (kontraksi), pleksus seliakus (simpatis), n. frenikus kanan (nyeri alih ke bahu).','A. sistika (cabang a. hepatika kanan); segitiga Calot.','Hati, duodenum, kolon transversum, duktus sistikus dan hepatikus.','Kolelitiasis (batu empedu), kolesistitis, kolik bilier, kolesistektomi.'),
'bile_duct':D('Duktus koledokus terbentuk dari penyatuan duktus sistikus dan duktus hepatikus komunis; bermuara di papila mayor duodenum.','Menyalurkan empedu ke duodenum; sfingter Oddi mengatur aliran.','N. vagus dan pleksus seliakus.','A. sistika, a. hepatika kanan, a. gastroduodenalis, a. pankreatikoduodenalis superior.','Ligamentum hepatoduodenale (bersama v. porta dan a. hepatika), kepala pankreas, duodenum.','Koledokolitiasis, kolangitis, ikterus obstruktif, karsinoma kepala pankreas.'),
'pancreas':D('Kelenjar panjang di belakang lambung (retroperitoneal) dengan kepala, leher, korpus, dan ekor; eksokrin dan endokrin.','Eksokrin: enzim pencernaan dan bikarbonat; endokrin: insulin, glukagon, somatostatin (pulau Langerhans).','N. vagus (sekresi) dan pleksus seliakus (simpatis).','A. splenika, a. pankreatikoduodenalis superior dan inferior; v. porta.','Duodenum (kepala), limpa (ekor), lambung, v. porta, aorta, v. kava inferior, ginjal kiri.','Pankreatitis akut dan kronis, karsinoma pankreas (kepala), diabetes melitus, pseudokista.'),
'pancreatic_duct':D('Duktus utama (Wirsung) menyatu dengan duktus koledokus di ampula Vater; duktus aksesori (Santorini) bermuara di papila minor.','Menyalurkan getah pankreas ke duodenum.','N. vagus dan pleksus seliakus.','A. pankreatikoduodenalis dan a. splenika.','Parenkim pankreas, duktus koledokus, duodenum.','Batu duktus, pankreatitis, striktur, pankreas divisum.'),
'omentum_major':D('Lipatan peritoneum besar yang menggantung dari kelengkungan mayor lambung menutupi usus seperti celemek.','Menyimpan lemak, melindungi organ, dan melokalisasi infeksi.','Pleksus seliakus (simpatis); saraf otonom yang menyertai pembuluh darah.','A. gastroepiploika kanan dan kiri.','Lambung, kolon transversum, usus halus, peritoneum.','Melokalisasi radang, torsi omentum, metastasis (omental cake).'),
'omentum_minor':D('Lipatan peritoneum dari kelengkungan minor lambung dan duodenum proksimal ke hati; ligamen hepatogastrik dan hepatoduodenal.','Menopang lambung, membawa pembuluh ke hati, dan membatasi bursa omentalis.','Pleksus seliakus dan n. vagus.','A. gastrika kanan dan kiri, a. hepatika, v. porta.','Hati, lambung, duodenum, foramen epiploikum (Winslow), duktus koledokus.','Manuver Pringle (menjepit ligamen hepatoduodenal), penyebaran tumor.'),
'mesocolon':D('Lipatan peritoneum yang menggantung kolon ke dinding abdomen posterior (mesokolon transversum dan sigmoid).','Membawa pembuluh darah, limfe, dan saraf ke kolon serta memberi mobilitas.','Pleksus mesenterika superior dan inferior.','A. kolika media, kiri, dan aa. sigmoid.','Kolon transversum atau sigmoid, pankreas, duodenum, aorta.','Volvulus pada mesokolon panjang, hernia internal, kolektomi.'),
'mesoappendix':D('Lipatan peritoneum kecil berbentuk segitiga yang menggantung apendiks pada mesenterium ileum terminal.','Membawa a. apendikularis ke apendiks.','Pleksus mesenterika superior.','A. apendikularis (cabang a. ileokolika).','Apendiks, ileum terminal, sekum.','Ligasi saat apendektomi; iskemia apendiks bila pembuluhnya tersumbat.')}
NM={'Uvula_of_palate':('Uvula','Uvula palatina','palate',0),'Soft_palate':('Palatum Molle','Palatum molle','palate',0),'Gingiva':('Gusi','Gingiva','gingiva',0),'Tongue':('Lidah','Lingua','tongue',0),'Parotid_gland':('Kelenjar Parotis','Glandula parotidea','parotid',0),'(Accessory_parotid_gland)':('Kelenjar Parotis Aksesori','Glandula parotis accessoria','parotid',1),'Parotid_duct':('Duktus Parotis (Stensen)','Ductus parotideus','salivary_duct',1),'Sublingual_gland':('Kelenjar Sublingual','Glandula sublingualis','sublingual',0),'Submandibular_gland':('Kelenjar Submandibula','Glandula submandibularis','submandibular',0),'Submandibular_duct':('Duktus Submandibula (Wharton)','Ductus submandibularis','salivary_duct',1),
'Oesophagus':('Esofagus','Oesophagus','esophagus',0),'Stomach':('Lambung','Gaster (Ventriculus)','stomach',0),'Mucosa_of_stomach':('Mukosa Lambung','Tunica mucosa gastris','stomach_mucosa',0),'Duodenum':('Duodenum','Duodenum','duodenum',0),'Jejunum':('Jejunum','Jejunum','jejunum',0),'Vermiform_appendix':('Apendiks Vermiformis','Appendix vermiformis','appendix',0),'Ascending_colon':('Kolon Asendens','Colon ascendens','colon_asc',0),'Transverse_colon':('Kolon Transversum','Colon transversum','colon_trans',0),'Descending_colon':('Kolon Desendens','Colon descendens','colon_desc',0),'Sigmoid_colon':('Kolon Sigmoid','Colon sigmoideum','colon_sig',0),'Free_taenia':('Taenia Libera','Taenia libera','taenia',1),'Mesocolic_taenia':('Taenia Mesokolika','Taenia mesocolica','taenia',1),'Omental_taenia':('Taenia Omentalis','Taenia omentalis','taenia',1),
'Liver':('Hati','Hepar','liver',0),'Gallbladder':('Kantung Empedu','Vesica biliaris','gallbladder',0),'Bile_duct':('Duktus Koledokus','Ductus choledochus','bile_duct',0),'Pancreas':('Pankreas','Pancreas','pancreas',0),'Pancreatic_duct':('Duktus Pankreatikus (Wirsung)','Ductus pancreaticus','pancreatic_duct',1),'Accessory_pancreatic_duct':('Duktus Pankreatikus Aksesori (Santorini)','Ductus pancreaticus accessorius','pancreatic_duct',1),
'Greater_omentum':('Omentum Mayus','Omentum majus','omentum_major',0),'Lesser_omentum':('Omentum Minus','Omentum minus','omentum_minor',0),'Mesocolon':('Mesokolon','Mesocolon','mesocolon',0),'Meso-appendix':('Mesoapendiks','Mesoappendix','mesoappendix',0)}
GN=['Rongga Mulut & Kelenjar Ludah','Saluran Cerna','Hati & Empedu','Pankreas','Peritoneum & Omentum']
GI={'Uvula_of_palate':0,'Soft_palate':0,'Gingiva':0,'Tongue':0,'Parotid_gland':0,'(Accessory_parotid_gland)':0,'Parotid_duct':0,'Sublingual_gland':0,'Submandibular_gland':0,'Submandibular_duct':0,'Liver':2,'Gallbladder':2,'Bile_duct':2,'Pancreas':3,'Pancreatic_duct':3,'Accessory_pancreatic_duct':3,'Greater_omentum':4,'Lesser_omentum':4,'Mesocolon':4,'Meso-appendix':4}
ROM={'I':1,'II':2,'III':3,'IV':4,'V':5,'VI':6,'VII':7,'VIII':8}
M=json.load(open('meta_cerna.json')); meta=M['meta']
its=collections.OrderedDict()
for i,m in enumerate(meta):
    b,s,side,t=cls.split(m[0]); it=its.setdefault(b,{'p':[],'s':set()}); it['p'].append(i)
    if side: it['s'].add(side)
def sidestr(s): return 'kanan & kiri' if s=={'r','l'} else 'kanan' if s=={'r'} else 'kiri' if s=={'l'} else 'garis tengah'
G=[[] for _ in GN]
for b,it in its.items():
    gen=0
    if b in NM: n,l,d,gen=NM[b]; g=GI.get(b,1); key=n
    else:
        m=re.match(r'^.*segment_of_liver_\((.+)\)$',b); r=m[1]; n='Segmen Hati '+r; l='Segmentum hepatis '+r; d='liver_seg'; gen=1; g=2; key='z%d'%ROM[r]
    if b=='Liver': key='a'
    o={'id':b,'n':n,'l':l,'e':b.replace('_',' '),'r':GN[g],'s':sidestr(it['s']),'p':it['p'],'d':d}
    if gen: o['g']=1
    G[g].append((key,o))
order={'Esofagus':0,'Lambung':1,'Mukosa Lambung':2,'Duodenum':3,'Jejunum':4,'Kolon Asendens':5,'Kolon Transversum':6,'Kolon Desendens':7,'Kolon Sigmoid':8,'Apendiks Vermiformis':9}
G[1]=[(order.get(k,20),o) for k,o in G[1]]
groups=[{'g':GN[i],'items':[o for _,o in sorted(G[i],key=lambda x:str(x[0]) if i!=1 else '%02d%s'%(x[0],x[1]['n']))]} for i in range(5)]
print([(g['g'],len(g['items'])) for g in groups])
for g in groups:
    for o in g['items']:
        assert o['d'] in DET,o
json.dump({'g':groups,'DET':DET},open('cerna_meta.json','w'),ensure_ascii=False)
blob=open('blob_cerna.b64').read()
open('/mnt/user-data/outputs/data/atlas_cerna.json','w').write(json.dumps({'b':blob,'m':M},separators=(',',':')))
